// Prepare context for AI generation
const topic = $items('Get Next Available Topic from Sheet')[0]?.json || {};
const livePosts = $items('Fetch Live Posts for Internal Linking').map(p => ({
  id: p.json.id,
  title: p.json.title?.rendered || 'Legal Article',
  url: p.json.link || '',
  slug: p.json.slug || ''
}));
const directoryEntries = $items('Read Directory Lookup Table').map(d => d.json);

// Determine Attorney Directory CTA behavior
const targetState = (topic.target_state || 'Federal').trim();
const practiceArea = (topic.practice_area || 'General Law').trim();

const matchingDirectory = directoryEntries.find(d => 
  d.state_name?.toLowerCase() === targetState.toLowerCase() &&
  (d.practice_area?.toLowerCase() === practiceArea.toLowerCase() || d.practice_area?.toLowerCase() === 'all')
);

let ctaConfig = {
  hasAttorneys: false,
  headline: 'Need Legal Assistance?',
  subheadline: `Get matched with a vetted attorney in ${targetState}.`,
  buttonText: 'Get Matched Now',
  targetUrl: `${$env.WORDPRESS_BASE_URL || 'https://common-law.ai'}/get-matched/`
};

if (matchingDirectory && matchingDirectory.has_active_attorneys === 'TRUE') {
  ctaConfig = {
    hasAttorneys: true,
    headline: matchingDirectory.cta_headline || `Need Legal Help in ${targetState}?`,
    subheadline: `Find a verified ${targetState} ${practiceArea} attorney today.`,
    buttonText: matchingDirectory.cta_button_text || `Find a ${targetState} Attorney`,
    targetUrl: matchingDirectory.custom_directory_url || `${$env.WORDPRESS_BASE_URL || 'https://common-law.ai'}/attorneys/?state=${encodeURIComponent(targetState.toLowerCase())}`
  };
}

return [{
  json: {
    topicId: topic.topic_id,
    topicTitle: topic.title_idea,
    primaryKeyword: topic.primary_keyword,
    targetState: targetState,
    practiceArea: practiceArea,
    livePostsContext: livePosts.slice(0, 10),
    ctaConfig: ctaConfig,
    disclaimer: 'Disclaimer: The information provided in this article is for educational and informational purposes only and does not constitute formal legal advice. No attorney-client relationship is formed by reading this content. For specific legal issues, always consult a licensed attorney in your jurisdiction.'
  }
}];

// Validate and parse the generated article payload
const raw = $json.message?.content || $json.text || '';
let articleData = {};

try {
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  articleData = JSON.parse(cleaned);
} catch (err) {
  throw new Error(`Failed to parse AI article JSON: ${err.message}. Raw output snippet: ${raw.substring(0, 200)}`);
}

const context = $items('Prepare Context & Directory CTA Logic')[0].json;

// Build FAQ Schema snippet to append to JSON-LD
let faqSchema = null;
if (Array.isArray(articleData.faq_items) && articleData.faq_items.length > 0) {
  faqSchema = {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": articleData.faq_items.map(faq => ({
      "@type": "Question",
      "name": faq.question,
      "acceptedAnswer": {
        "@type": "Answer",
        "text": faq.answer
      }
    }))
  };
}

// Dynamic CTA Banner HTML snippet
const cta = context.ctaConfig;
const ctaHtml = `
<div class="commonlaw-attorney-cta" style="margin: 40px 0; padding: 28px; background: linear-gradient(135deg, #1e293b, #0f172a); border-radius: 12px; color: #ffffff; text-align: center; border: 1px solid #334155; box-shadow: 0 4px 20px rgba(0,0,0,0.15);">
  <h3 style="color: #f8fafc; font-size: 22px; margin-bottom: 8px; font-weight: 700;">${cta.headline}</h3>
  <p style="color: #cbd5e1; font-size: 16px; margin-bottom: 20px;">${cta.subheadline}</p>
  <a href="${cta.targetUrl}" style="display: inline-block; background-color: #2563eb; color: #ffffff; padding: 12px 28px; border-radius: 8px; text-decoration: none; font-weight: 600; font-size: 15px; transition: background 0.2s;">${cta.buttonText} &rarr;</a>
</div>
`;

// Legal Disclaimer HTML snippet
const disclaimerHtml = `
<div class="commonlaw-legal-disclaimer" style="margin-top: 36px; padding: 16px 20px; background-color: #f1f5f9; border-left: 4px solid #64748b; font-size: 13px; color: #475569; font-style: italic;">
  ${context.disclaimer}
</div>
`;

// FAQ Section HTML snippet
let faqHtml = '';
if (Array.isArray(articleData.faq_items) && articleData.faq_items.length > 0) {
  faqHtml = `
  <div class="commonlaw-faq-section" style="margin-top: 36px;">
    <h2>Frequently Asked Questions</h2>
    ${articleData.faq_items.map(f => `
      <div class="faq-item" style="margin-bottom: 20px;">
        <h3 style="font-size: 18px; margin-bottom: 6px;">${f.question}</h3>
        <p>${f.answer}</p>
      </div>
    `).join('')}
  </div>
  `;
}

// Combine complete article HTML content
const fullHtmlContent = `
${articleData.article_html || ''}
${faqHtml}
${ctaHtml}
${disclaimerHtml}
<script type="application/ld+json">${JSON.stringify(articleData.json_ld_schema || {})}</script>
${faqSchema ? `<script type="application/ld+json">${JSON.stringify(faqSchema)}</script>` : ''}
`.trim();

return [{
  json: {
    topicId: context.topicId,
    title: articleData.h1 || context.topicTitle,
    seoTitle: articleData.seo_title || context.topicTitle,
    metaDescription: articleData.meta_description || '',
    slug: articleData.slug || context.topicTitle.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, ''),
    excerpt: articleData.excerpt || '',
    contentHtml: fullHtmlContent,
    categories: articleData.categories || [context.targetState, context.practiceArea],
    tags: articleData.tags || [context.primaryKeyword, 'common law'],
    imagePrompt: articleData.image_prompt || `Professional legal consultation in ${context.targetState}, high detail, 1600x900 editorial aesthetic`,
    imageAltText: articleData.image_alt_text || `${context.topicTitle} - common-law.ai`,
    jsonLdSchema: articleData.json_ld_schema,
    targetState: context.targetState,
    practiceArea: context.practiceArea
  }
}];
